def table(rows,widths=None):
 rows=[[p(html.escape(str(c)),True) for c in row] for row in rows]
 t=Table(rows,colWidths=widths or [content/len(rows[0])]*len(rows[0]),repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4edf6')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,0),1,colors.HexColor('#245580')),('LINEBELOW',(0,1),(-1,-1),.4,colors.HexColor('#d8e1eb'))]));return t
