def md_sections(name):
 s=(d/name).read_text(encoding='utf-8')
 elements=[]
 for block in s.split('\n\n'):
  if not block.strip():continue
  if block.startswith('# '):continue
  if block.startswith('## '):elements.append(h(html.escape(block[3:].strip())))
  else:
   text=html.escape(block).replace('\n','<br/>');text=re.sub(r'\*\*(.*?)\*\*',r'<b>\1</b>',text);elements.append(p(text))
 return elements
stats=json.loads((d/'evidencias/s14-estabilizacion/resumen-e2e.json').read_text(encoding='utf-8'))
